 Future<void> novo() async {final nome=TextEditingController(), login=TextEditingController(), senha=TextEditingController(), telefone=TextEditingController(), percentual=TextEditingController(text:'75'); final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Novo colaborador'),content:SizedBox(width:440,child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:nome,decoration:const InputDecoration(labelText:'Nome *')),TextField(controller:login,decoration:const InputDecoration(labelText:'Usuário de acesso *')),TextField(controller:senha,obscureText:true,decoration:const InputDecoration(labelText:'Senha *')),TextField(controller:telefone,decoration:const InputDecoration(labelText:'Telefone')),TextField(controller:percentual,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Percentual sobre recebimentos'))])),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Cadastrar'))])); if(ok!=true)return; final r=await apiService.post('/api/funcionarios',body:{'nome':nome.text.trim(),'login':login.text.trim(),'senha':senha.text,'telefone':telefone.text.trim(),'percentualMensalidade':double.tryParse(percentual.text.replaceAll(',','.'))??75});if(!mounted)return;if(r.statusCode>=200&&r.statusCode<300){setState(()=>dados=carregar());ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Colaborador cadastrado. Agora vincule as piscinas a ele.')));}else{ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Não foi possível cadastrar (${r.statusCode}).')));}}
 @override Widget build(BuildContext c)=>_PaginaLista(titulo:'Colaboradores',subtitulo:'Cadastre os acessos e depois defina as piscinas de responsabilidade.',acao:'Novo colaborador',onAcao:novo,futuro:dados,item:(f){final u=f['usuario']??{};return ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text(u['nome']??''),subtitle:Text('Usuário: ${u['login']??''} • ${f['telefone']??'sem telefone'}'),trailing:Text('${f['percentualMensalidade']??75}%'));});
}

class _PiscinasPage extends StatefulWidget {const _PiscinasPage({required this.gestor});final bool gestor;@override State<_PiscinasPage> createState()=>_PiscinasPageState();}
