 Future<void> novo() async {final clientes=await _lista('/api/clientes');final funcs=await _lista('/api/funcionarios');if(clientes.isEmpty||!mounted)return;int cliente=clientes.first['id'];int? responsavel=funcs.isEmpty?null:funcs.first['id'];final nome=TextEditingController(),endereco=TextEditingController(),tipo=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(_,setL)=>AlertDialog(title:const Text('Nova piscina'),content:SizedBox(width:500,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<int>(initialValue:cliente,decoration:const InputDecoration(labelText:'Cliente *'),items:clientes.map<DropdownMenuItem<int>>((x)=>DropdownMenuItem(value:x['id'],child:Text(x['nome']))).toList(),onChanged:(x)=>setL(()=>cliente=x!)),TextField(controller:nome,decoration:const InputDecoration(labelText:'Nome ou identificação *')),TextField(controller:endereco,maxLines:2,decoration:const InputDecoration(labelText:'Endereço da piscina *')),TextField(controller:tipo,decoration:const InputDecoration(labelText:'Tipo')),DropdownButtonFormField<int>(initialValue:responsavel,decoration:const InputDecoration(labelText:'Colaborador responsável'),items:funcs.map<DropdownMenuItem<int>>((x)=>DropdownMenuItem(value:x['id'],child:Text((x['usuario']??{})['nome']??''))).toList(),onChanged:(x)=>setL(()=>responsavel=x))]))),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Cadastrar'))])));if(ok!=true)return;final r=await apiService.post('/api/piscinas',body:{'clienteId':cliente,'nome':nome.text.trim(),'endereco':endereco.text.trim(),'tipo':tipo.text.trim(),'responsavelId':responsavel,'observacoes':''});if(!mounted)return;if(r.statusCode>=200&&r.statusCode<300){setState(()=>dados=carregar());ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Piscina cadastrada.')));}else{ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Não foi possível salvar (${r.statusCode}).')));}}
 Future<List<dynamic>> _lista(String url)async{final r=await apiService.get(url);return r.statusCode==200?jsonDecode(r.body):[];}
 Future<void> excluir(Map<String,dynamic> p) async {final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Excluir piscina?'),content:Text('Excluir ${p['nome']}?'),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Excluir'))]));if(ok==true){final r=await apiService.delete('/api/piscinas/${p['id']}');if(r.statusCode>=200&&r.statusCode<300)setState(()=>dados=carregar());}}
 Future<void> editar(Map<String,dynamic> p) async {final nome=TextEditingController(text:p['nome']??''),endereco=TextEditingController(text:p['endereco']??''),tipo=TextEditingController(text:p['tipo']??'');final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Editar piscina'),content:SizedBox(width:440,child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:nome,decoration:const InputDecoration(labelText:'Nome')),TextField(controller:endereco,decoration:const InputDecoration(labelText:'Endereço')),TextField(controller:tipo,decoration:const InputDecoration(labelText:'Tipo'))])),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Salvar'))]));if(ok==true){final r=await apiService.put('/api/piscinas/${p['id']}',body:{'clienteId':(p['cliente']??{})['id'],'responsavelId':(p['responsavel']??{})['id'],'nome':nome.text.trim(),'endereco':endereco.text.trim(),'tipo':tipo.text.trim(),'volumeLitros':p['volumeLitros'],'observacoes':p['observacoes']??''});if(r.statusCode>=200&&r.statusCode<300)setState(()=>dados=carregar());}}
  @override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.all(28),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Piscinas',style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),Text(widget.gestor?'Cada piscina tem endereço, cliente e responsável.':'Somente suas piscinas de responsabilidade.')])),if(widget.gestor)FilledButton.icon(onPressed:novo,icon:const Icon(Icons.add),label:const Text('Nova piscina'))]),const SizedBox(height:18),TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Pesquisar piscina, cliente ou endereço',border:OutlineInputBorder()),onChanged:(_)=>setState((){})),const SizedBox(height:12),Expanded(child:FutureBuilder<List<dynamic>>(future:dados,builder:(_,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text('${s.error}'));if(s.data!.isEmpty)return const Center(child:Text('Nenhuma piscina cadastrada.'));return Card(child:ListView.separated(itemCount:s.data!.length,separatorBuilder:(_,__)=>const Divider(height:1),itemBuilder:(_,i){final p=s.data![i] as Map<String,dynamic>;final cl=p['cliente']??{},resp=p['responsavel']??{},u=resp['usuario']??{};return ListTile(leading:const CircleAvatar(child:Icon(Icons.pool)),title:Text(p['nome']??''),subtitle:Text('${cl['nome']??''} • ${p['endereco']??'endereço não informado'}'),trailing:Row(mainAxisSize:MainAxisSize.min,children:[Text(u['nome']??'Sem responsável'),if(widget.gestor)IconButton(icon:const Icon(Icons.edit_outlined),onPressed:()=>editar(p)),if(widget.gestor)IconButton(icon:const Icon(Icons.delete_outline,color:Colors.red),onPressed:()=>excluir(p))]));}));}))]));}

class _CobrancasPage extends StatefulWidget{const _CobrancasPage();@override State<_CobrancasPage> createState()=>_CobrancasPageState();}
class _CobrancasPageState extends State<_CobrancasPage>{late Future<List<dynamic>> dados;@override void initState(){super.initState();dados=carregar();}Future<List<dynamic>> carregar()async{final r=await apiService.get('/api/cobrancas');if(r.statusCode!=200)throw Exception('Não foi possível carregar cobranças.');return jsonDecode(r.body);}Future<void> pagar(Map<String,dynamic> x)async{final pago=x['status']=='PAGO';final r=await apiService.put(pago?'/api/cobrancas/${x['id']}/reabrir':'/api/cobrancas/${x['id']}/baixar?valor=${x['total']}');if(r.statusCode>=200&&r.statusCode<300)setState(()=>dados=carregar());}
 @override Widget build(BuildContext c)=>_PaginaLista(titulo:'Cobranças',subtitulo:'Mensalidades e valores de produtos e serviços.',futuro:dados,item:(x){final pago=x['status']=='PAGO';return ListTile(leading:Icon(pago?Icons.check_circle:Icons.pending_actions,color:pago?Colors.green:Colors.orange),title:Text((x['cliente']??{})['nome']??''),subtitle:Text('Vencimento: ${x['vencimento']} • ${x['status']}'),trailing:Row(mainAxisSize:MainAxisSize.min,children:[Text(formatarMoeda(x['total'] as num)),Switch(value:pago,onChanged:(_)=>pagar(x))]));});}

