class _PaginaLista extends StatelessWidget{const _PaginaLista({required this.titulo,required this.subtitulo,required this.futuro,required this.item,this.acao,this.onAcao});final String titulo,subtitulo;final Future<List<dynamic>> futuro;final Widget Function(Map<String,dynamic>) item;final String? acao;final VoidCallback? onAcao;@override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.all(28),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(titulo,style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:6),Text(subtitulo)])),if(acao!=null)FilledButton.icon(onPressed:onAcao,icon:const Icon(Icons.add),label:Text(acao!))]),const SizedBox(height:20),Expanded(child:FutureBuilder<List<dynamic>>(future:futuro,builder:(_,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text('${s.error}'));if(s.data!.isEmpty)return const Center(child:Text('Nenhum registro encontrado.'));return Card(child:ListView.separated(itemCount:s.data!.length,separatorBuilder:(_,__)=>const Divider(height:1),itemBuilder:(_,i)=>item(s.data![i] as Map<String,dynamic>)));}))]));}



